/// A one-shot reply capability: a token of the core's, or one minted on
/// another node and decoded here.
pub struct SalvoReply {
    inner: Mutex<ReplyInner>,
    check: Option<SalvoReplyCheck>,
    /// [wire-format] How a task's answer is decoded should it come back
    /// over the wire.
    decode: Option<ReplyDecoder>,
}

enum ReplyInner {
    Local(Option<crate::runtime::Token>),
    Remote(crate::runtime_routing::ReplyParts),
}

impl SalvoReply {
    fn local(t: crate::runtime::Token, decode: Option<ReplyDecoder>) -> Self {
        SalvoReply { inner: Mutex::new(ReplyInner::Local(Some(t))), check: None, decode }
    }

    fn take_local(&self) -> Option<crate::runtime::Token> {
        match &mut *self.inner.lock().unwrap() {
            ReplyInner::Local(t) => t.take(),
            ReplyInner::Remote(_) => None,
        }
    }

    /// Sends the reply, consuming the token. Enqueue only — user code never
    /// runs inside a `send`.
    pub fn send(self, value: SalvoMsg) {
        if let Some(check) = &self.check {
            check(&*value);
        }
        match self.take_local() {
            Some(t) => crate::runtime::answer(t, Dyn { v: value }),
            None => panic!("internal: an untyped reply to a remote token"),
        }
    }

    /// [platform-check] This token, checking what is sent on it.
    pub fn checked(mut self, check: SalvoReplyCheck) -> Self {
        self.check = Some(check);
        self
    }

    /// [platform-reply] Hands the token to host code that completes it later,
    /// from any thread; until then the program has an outside source of work.
    pub fn hosted(self) -> SalvoHostReply {
        crate::runtime::external_begin();
        SalvoHostReply { reply: Some(self) }
    }
}

/// [platform-reply] A reply the host has taken on.
pub struct SalvoHostReply {
    reply: Option<SalvoReply>,
}

impl SalvoHostReply {
    /// Completes the reply with `value`, from any thread.
    pub fn send<T: Any + Send>(mut self, value: T) {
        // Checked while the token is still held: a refused value unwinds
        // through `Drop`, which closes the outside source.
        if let Some(check) = self.reply.as_ref().and_then(|r| r.check.clone()) {
            check(&value);
        }
        let mut reply = self.reply.take().expect("a host reply holds its token until sent");
        reply.check = None;
        if matches!(&*reply.inner.lock().unwrap(), ReplyInner::Remote(_)) {
            panic!(
                "salvo: a host-completed reply to a token minted on another node is not \
                 supported yet [platform-reply]"
            );
        }
        reply.send(Box::new(value));
        crate::runtime::external_end();
    }
}

impl Drop for SalvoHostReply {
    /// [platform-reply] The host dropped a reply unsent: reported, and the
    /// outside source closed, so a frame waiting on it reports the deadlock
    /// it is in instead of waiting forever in silence.
    fn drop(&mut self) {
        if self.reply.take().is_none() {
            return;
        }
        crate::runtime::external_end();
        eprintln!("salvo: a host reply was dropped without being sent [platform-reply]");
    }
}

