// [addr-routable] The codecs of the two scheduler handles live here, beside
// what they ask, so the wire stands alone in a program with no actors.

/// [addr-routable] An `Addr<E>` is a scheduler index in generated code; on
/// the wire it is its routable identity `(node, actor, bits)`, 24 bytes.
impl crate::wire::__Wire for usize {
    fn __enc(&self, out: &mut Vec<u8>) {
        let r = salvo_addr_identity(*self);
        out.extend_from_slice(&r.node.to_be_bytes());
        out.extend_from_slice(&r.actor.to_be_bytes());
        out.extend_from_slice(&r.bits.to_be_bytes());
    }
    fn __dec(r: &mut crate::wire::__Reader<'_>) -> Option<Self> {
        let node = r.u64()?;
        let actor = r.u64()?;
        let bits = r.u64()?;
        Some(salvo_import_addr(RemoteRef { node, actor, bits }))
    }
}

/// [addr-routable] A `Reply<T>` on the wire: `(node, kind, id, slot, bits)`,
/// 33 bytes.
impl crate::wire::__Wire for SalvoReply {
    fn __enc(&self, out: &mut Vec<u8>) {
        let p = salvo_reply_export(self);
        out.extend_from_slice(&(p.node as u64).to_be_bytes());
        out.push(p.kind as u8);
        out.extend_from_slice(&(p.id as u64).to_be_bytes());
        out.extend_from_slice(&(p.slot as u64).to_be_bytes());
        out.extend_from_slice(&(p.bits as u64).to_be_bytes());
    }
    fn __dec(r: &mut crate::wire::__Reader<'_>) -> Option<Self> {
        let node = r.u64()? as i64;
        let kind = r.u8()? as i32;
        let id = r.u64()? as i64;
        let slot = r.u64()? as i64;
        let bits = r.u64()? as i64;
        Some(salvo_reply_import(crate::runtime_routing::ReplyParts { node, kind, id, slot, bits }))
    }
}
